// Human-entered observations only. A missing check is never a passing check.
export const OBSERVATION_KEY='fixiverse-observations-v1';
export const OBS_PHASES=['Before','Play','After','Next-day'];
export const OBS_KINDS=['UI instruction','Math help','Access support','Blocked control','Reading confusion','Layout','Keyboard','Screen reader','Navigation','Other'];
export const OBS_CHECKS=[['first-step','First step','Can the child open a mission and identify the next action without interface coaching?'],['touch','Actual touch device','On the actual phone/tablet, can the learner reach controls without mistaps or clipped content?'],['keyboard','Keyboard only','Reach and operate answers, selects and next steps with Tab, Shift+Tab, Enter and arrow keys.'],['focus','Focus and dialogs','Focus is visible; dialogs close with Escape and return focus; a new screen has a meaningful heading.'],['reader','Actual screen reader','Using a named real screen reader, inspect headings, control names, selected states, feedback and reading order.'],['zoom','Zoom / larger text','At 200% browser zoom or the learner’s needed text setting, read and operate content without losing controls.'],['meaning','Beyond color','Identify pieces and tiles using labels, shapes or patterns without relying on color alone.'],['motion','Motion control','Pause the bookshelf tour and test the reduced-motion setting if relevant to the learner.'],['voice','Read aloud','On this device, check speech availability, pronunciation, stopping and whether it helps this learner.'],['resume','Save / resume','Back up first, reload, then verify the same learner and unfinished activity resume on this browser.']];
const clean=(s,n=240)=>String(s??'').trim().slice(0,n),validID=id=>typeof id==='string'&&/^[a-zA-Z0-9-]{1,80}$/.test(id);
export const newObservations=()=>({version:1,active:null,sessions:[]});
export function restoreObservations(raw){
 if(!raw||raw.version!==1||!Array.isArray(raw.sessions)||raw.sessions.length>40)throw Error('The observation notebook could not be restored.');const out=structuredClone(raw),ids=new Set();
 for(const s of out.sessions){if(!validID(s.id)||ids.has(s.id)||!OBS_PHASES.includes(s.phase)||!Number.isFinite(s.startedAt)||s.startedAt<0||(s.endedAt!==null&&(!Number.isFinite(s.endedAt)||s.endedAt<s.startedAt))||!Array.isArray(s.events)||s.events.length>200||!s.checks||typeof s.checks!=='object'||Array.isArray(s.checks))throw Error('A saved observation session is invalid.');ids.add(s.id);for(const k of ['device','browser','input','tools','environment'])if(typeof s[k]!=='string'||s[k].length>120)throw Error('Saved device notes are invalid.');if(!['Actual device','Browser viewport simulation','Not specified'].includes(s.environment))throw Error('Choose how this device was tested.');const eventIDs=new Set();for(const e of s.events){if(!validID(e.id)||eventIDs.has(e.id)||!OBS_KINDS.includes(e.kind)||!['Minor','Needs help','Blocker'].includes(e.severity)||!['Open','Fixed - needs retest','Retested'].includes(e.status)||!Number.isInteger(e.quantity)||e.quantity<1||e.quantity>20||!Number.isFinite(e.at)||e.at<s.startedAt||typeof e.voided!=='boolean'||!Number.isInteger(e.helpLevel)||e.helpLevel<0||e.helpLevel>3)throw Error('A saved barrier is invalid.');eventIDs.add(e.id);for(const k of ['screen','context','tried','help','note'])if(typeof e[k]!=='string'||e[k].length>240)throw Error('A saved barrier note is too long.');}for(const [k,c]of Object.entries(s.checks))if(!OBS_CHECKS.some(x=>x[0]===k)||!['Pass','Barrier','Not applicable','Not run'].includes(c.status)||typeof c.note!=='string'||c.note.length>240||c.status!=='Not run'&&!c.note.trim())throw Error('A saved device check is invalid.');}
 if(out.active!==null&&!out.sessions.some(s=>s.id===out.active&&s.endedAt===null))throw Error('The active observation session is invalid.');return out;
}
export function observationStep(old,a,now=Date.now(),id=globalThis.crypto?.randomUUID?.()){
 const s=restoreObservations(old);if(!Number.isFinite(now)||now<0)throw Error('Check the device clock.');
 if(a.type==='start'){if(s.active)throw Error('Finish the current observation before starting another.');if(s.sessions.length>=40)throw Error('This notebook is full. Export it before starting a new notebook.');if(!validID(id)||s.sessions.some(x=>x.id===id)||!OBS_PHASES.includes(a.phase))throw Error('Choose a visit phase.');const session={id,phase:a.phase,startedAt:now,endedAt:null,device:clean(a.device,120),browser:clean(a.browser,120),input:clean(a.input,120),tools:clean(a.tools,120),environment:a.environment||'Not specified',events:[],checks:{}};if(!session.device||!session.browser)throw Error('Record a device and browser label, such as “iPad / Safari”.');s.sessions.push(session);s.active=id;}
 else{const session=s.sessions.find(x=>x.id===(a.session||s.active));if(!session)throw Error('Choose an observation session.');if(a.type==='log'){if(session.endedAt!==null)throw Error('This observation has ended. Start a new visit to add events.');if(session.events.length>=200||!validID(id)||session.events.some(e=>e.id===id))throw Error('This observation log is full or its ID is duplicated.');session.events.push({id,at:Math.max(now,session.startedAt),screen:clean(a.screen),context:clean(a.context),kind:a.kind,severity:a.severity||'Needs help',quantity:a.quantity??1,helpLevel:a.helpLevel??0,tried:clean(a.tried),help:clean(a.help),note:clean(a.note),status:'Open',voided:false});}
 else if(a.type==='edit'){const e=session.events.find(x=>x.id===a.id);if(!e)throw Error('Choose a recorded barrier.');for(const k of ['tried','help','note'])if(a[k]!==undefined)e[k]=clean(a[k]);if(a.status==='Retested'&&!e.note)throw Error('Record how you retested the fix in the note before marking Retested.');if(a.status!==undefined)e.status=a.status;if(a.voided!==undefined)e.voided=!!a.voided;}
 else if(a.type==='check'){if(!OBS_CHECKS.some(x=>x[0]===a.key))throw Error('Choose a device check.');const note=clean(a.note);if(a.status!=='Not run'&&!note)throw Error('Describe what you actually tested and observed, or keep Not run.');if(a.status==='Pass'&&a.key==='touch'&&session.environment!=='Actual device')throw Error('A viewport simulation cannot pass the actual touch-device check.');if(a.status==='Pass'&&a.key==='reader'&&(!session.tools.trim()||/^(none|unknown|not run|n\/a)$/i.test(session.tools.trim())))throw Error('Record the actual screen reader in the session’s assistive-tools field before marking this check passed.');session.checks[a.key]={status:a.status,note};}
 else if(a.type==='end'){if(session.endedAt!==null)throw Error('This visit is already finished.');session.endedAt=Math.max(now,session.startedAt);s.active=null;}
 else throw Error('Unknown observation action.');}
 return restoreObservations(s);
}
export function observationSummary(session){const events=session.events.filter(e=>!e.voided),count=kind=>events.filter(e=>e.kind===kind).reduce((n,e)=>n+e.quantity,0),checks=OBS_CHECKS.map(([key])=>session.checks[key]?.status||'Not run');return{ui:count('UI instruction'),math:count('Math help'),access:count('Access support'),openBlockers:events.filter(e=>e.severity==='Blocker'&&e.status!=='Retested').length,pendingNotes:events.filter(e=>!e.tried&&!e.help&&!e.note).length,loggedEvents:events.length,checksPass:checks.filter(x=>x==='Pass').length,checksBarrier:checks.filter(x=>x==='Barrier').length,checksNotRun:checks.filter(x=>x==='Not run').length};}
const obsCSV=rows=>rows.map(row=>row.map(v=>{let s=String(v??'');if(/^\s*[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}).join(',')).join('\r\n');
export function observationExport(alias,model){model=restoreObservations(model);const sessions=[['Learner','Session ID','Phase','Started','Ended','Device','Browser','Input','Assistive tools','Environment','UI instructions logged','Math help logged','Access supports logged','Open blockers','Marks needing notes','Device checks pass','Device checks barrier','Device checks not run']],barriers=[['Learner','Phase','Screen','Kind','Severity','Quantity','Tried','Help','Note','Status','Excluded','Session ID','Timestamp','Context','Math help level']],checks=[['Learner','Session ID','Phase','Device','Browser','Assistive tools','Environment','Check','Status','Evidence']];
 for(const s of model.sessions){const c=observationSummary(s);sessions.push([alias,s.id,s.phase,new Date(s.startedAt).toISOString(),s.endedAt===null?'In progress':new Date(s.endedAt).toISOString(),s.device,s.browser,s.input,s.tools,s.environment,c.ui,c.math,c.access,c.openBlockers,c.pendingNotes,c.checksPass,c.checksBarrier,c.checksNotRun]);for(const e of s.events)barriers.push([alias,s.phase,e.screen,e.kind,e.severity,e.quantity,e.tried,e.help,e.note,e.status,e.voided,s.id,new Date(e.at).toISOString(),e.context,e.helpLevel]);for(const [key,label]of OBS_CHECKS){const check=s.checks[key]||{status:'Not run',note:''};checks.push([alias,s.id,s.phase,s.device,s.browser,s.tools,s.environment,label,check.status,check.note]);}}
 return{sessions:obsCSV(sessions),barriers:obsCSV(barriers),checks:obsCSV(checks)};
}
